{"implementation":"import re

def solve(case):
    lines = case.get("lines", [])
    pattern = re.compile(r"^(Thought|Action|Observation|Final):\s*(.*)$", re.IGNORECASE)
    trajectory = []
    state = 0  # 0=start, 1=after_thought, 2=after_action, 3=after_observation, 4=after_final
    for i, line in enumerate(lines):
        match = pattern.match(line)
        if not match:
            return {"valid": False, "error_line": i + 1, "trajectory": trajectory}
        type_str = match.group(1).lower()
        content = match.group(2)
        allowed = False
        if state == 0:
            if type_str == "thought":
                allowed = True
                state = 1
        elif state == 1:
            if type_str == "action":
                allowed = True
                state = 2
            elif type_str == "final":
                allowed = True
                state = 4
        elif state == 2:
            if type_str == "observation":
                allowed = True
                state = 3
        elif state == 3:
            if type_str == "thought":
                allowed = True
                state = 1
        if not allowed:
            return {"valid": False, "error_line": i + 1, "trajectory": trajectory}
        trajectory.append({"type": type_str, "content": content})
    if state == 4:
        return {"valid": True, "error_line": None, "trajectory": trajectory}
    else:
        return {"valid": False, "error_line": len(lines) + 1, "trajectory": trajectory}
"}
